    /**
     * Ubah teks status dan persentase. persen &lt; 0 = progress berjalan tanpa persen.
     */
    public void setStatus(String teks, int persen) {
        LblStatus.setText(teks);
        Progress.setIndeterminate(persen < 0);
        if (persen >= 0) {
            Progress.setValue(persen);
        }
    }

